pushd $SRC/cups
sed -i '2110s/\(\s\)f->value/\1(int)f->value/' cups/ppd-cache.c
LSB_BUILD=y ./configure --prefix="$WORK" --libdir="$OUT" --disable-gnutls    --disable-libusb --with-components=core
make clean
make install-headers install-libs
make -C filter libs install-libs
install -m755 cups-config "$WORK"/cups-config
popd
rm -rf cups/libs || die
rm -rf freetype || die
rm -rf libpng || die
rm -rf zlib || die
cp -r $SRC/freetype freetype
CUPSCONFIG="$WORK/cups-config"
CUPS_CFLAGS=$($CUPSCONFIG --cflags)
CUPS_LDFLAGS=$($CUPSCONFIG --ldflags)
CUPS_LIBS=$($CUPSCONFIG --image --libs)
export CXXFLAGS="$CXXFLAGS $CUPS_CFLAGS"
CPPFLAGS="${CPPFLAGS:-} $CUPS_CFLAGS -DPACIFY_VALGRIND" ./autogen.sh   CUPSCONFIG=$CUPSCONFIG   --enable-freetype --enable-fontconfig   --enable-cups --with-ijs --with-jbig2dec   --with-drivers=cups,ljet4,laserjet,pxlmono,pxlcolor,pcl3,uniprint
make -j$(nproc) libgs
$CXX $CXXFLAGS $CUPS_LDFLAGS -std=c++11 -I.     $SRC/gstoraster_fuzzer.cc     -o "$OUT/gstoraster_fuzzer"     -Wl,-rpath='$ORIGIN'     $CUPS_LIBS     $LIB_FUZZING_ENGINE bin/gs.a
mkdir -p "$WORK/seeds"
for f in examples/*.{ps,pdf}; do
  s=$(sha1sum "$f" | awk '{print $1}')
  cp "$f" "$WORK/seeds/$s"
done
zip -j "$OUT/gstoraster_fuzzer_seed_corpus.zip" "$WORK"/seeds/*
